function() {

  // Попытка найти элемент на странице с промо
  var promoTitle = document.querySelector('.promo-bg_title h1');
  if (promoTitle) {
    return promoTitle.textContent.trim();
  }

  // Попытка найти элемент на странице с расписанием
  var scheduleItem = document.querySelector('.schedule_channel_item.active.playing .schedule_channel_item_name');
  if (scheduleItem) {
    var cloneSchedule = scheduleItem.cloneNode(true);
    var childSpan = cloneSchedule.querySelector('.schedule_channel_item_info');
    if (childSpan) {
      childSpan.remove();
    }
    return cloneSchedule.textContent.trim();
  }

  //Всплывашка над видео
  var controlTitle = document.querySelector('.video_controls_about_title');
  if (controlTitle) {
    return controlTitle.textContent.trim();
  }

  // Возвращаем undefined, если ни один элемент не найден
  return undefined;
}

function() {
  var element = document.querySelector('.video_controls_about_channel_logo img');
  var channelTitle = element ? element.getAttribute('alt') : null;

  if (channelTitle) {
    return channelTitle;
  } else {
    var element2 = document.querySelector('.page_tv_channel_item.active');
    var channelTitle2 = element2 ? element2.getAttribute('title') : null;

    if (channelTitle2) {
      return channelTitle2;
    } else {
      var elementsList = document.querySelectorAll('.page_tv_channel_item');
      var foundTitle = null;

      elementsList.forEach(function(el) {
        var scheduleBlock = el.querySelector('.page_tv_channel_item_schedule.invisible_scroll');
        if (scheduleBlock) {
          foundTitle = el.getAttribute('title');
        }
      });

      return foundTitle;
    }
  }
}

function() {
  var form = document.querySelector('.auth_cont_form');
  if (form) {
    var input = form.querySelector('.auth_cont_input');
    if (input) {
      return input.getAttribute('id');
    }
  }
  return null;
}

function() {
  var query = window.location.search.match(/[\?&]q=([^&#]*)/);
  return query ? decodeURIComponent(query[1].replace(/\+/g, ' ')) : null;
}

function() {
    // Главный экран промокода
    if (document.querySelector('.promo_modal_col') 
        && document.querySelector('.promo_modal_title') 
        && document.querySelector('.modal_input')) {
        return 'promo_main';
    }

    // Экран ввода телефона
    if (document.querySelector('.auth_cont_form') && document.querySelector('#phone')) {
        return 'promo_phone';
    }

    // Экран подтверждения номера телефона (код из СМС)
    if (document.querySelector('.auth_cont_form') && document.querySelector('input[autocomplete="one-time-code"]')) {
        return 'promo_sms';
    }

    // Экран привязки карты
    if (document.querySelector('.promo_modal_packet_info') 
        && document.querySelector('.promo_modal_cont')) {
        return 'check_card';
    }

    // Экран успешного применения промокода
    if (document.querySelector('.promo_modal_finish_cont')) {
        return 'promo_success';
    }

    return 'unknown';
}

function() {
    var promoCodeElement = document.querySelector('#code'); // Ищем элемент с ID "code"
    if (promoCodeElement) {
        return promoCodeElement.value || ''; // Возвращаем значение поля, если оно существует
    }
    return ''; // Если элемент не найден, возвращаем пустое значение
}

function() {
    // Получаем все элементы img, которые содержат '/img/promo/' в src
    var images = document.querySelectorAll('img[src*="/img/promo/"]');
    var visibleBanner = null; // Переменная для хранения названия видимого баннера
    var maxVisibleArea = 0; // Переменная для хранения максимальной видимой площади

    // Проходим по всем подходящим изображениям и проверяем их видимость по горизонтали
    images.forEach(function(img) {
        var rect = img.getBoundingClientRect();

        // Вычисляем центр изображения по горизонтали
        var centerX = rect.left + rect.width / 2;

        // Проверяем, находится ли центр изображения в пределах видимой области
        if (centerX > 0 && centerX < (window.innerWidth || document.documentElement.clientWidth)) {
            // Вычисляем видимую площадь баннера
            var visibleArea = Math.max(0, Math.min(rect.right, window.innerWidth || document.documentElement.clientWidth) - Math.max(rect.left, 0));

            // Если текущая видимая площадь больше предыдущей максимальной, обновляем visibleBanner
            if (visibleArea > maxVisibleArea) {
                maxVisibleArea = visibleArea;
                visibleBanner = img.getAttribute('alt'); // Извлекаем атрибут alt
            }
        }
    });

    // Возвращаем название видимого баннера, если найден
    return visibleBanner;
}

function() {
  // Ищем элемент h1 внутри элемента с классом "page_subhead"
  var h1Element = document.querySelector('.page_subhead h1');

  // Проверяем, найден ли элемент h1
  if (h1Element) {
    // Возвращаем текстовое содержимое элемента h1
    return h1Element.textContent.trim();
  }

  // Если элемент не найден, возвращаем null
  return null;
}

function() {
    // Получаем все элементы с классом '.page_subhead_active'
    var colTitles = document.querySelectorAll('.page_subhead_active a[aria-label]');
    var visibleCollectionTitle = null; // Переменная для хранения названия самого верхнего видимого элемента
    var minTop = Infinity; // Изначально устанавливаем минимальный top на максимально возможное значение

    // Проходим по всем найденным элементам и проверяем их видимость
    colTitles.forEach(function(title) {
        var rect = title.getBoundingClientRect();

        // Проверяем, виден ли элемент на экране (по вертикали и горизонтали)
        if (
            rect.top >= 0 &&
            rect.left >= 0 &&
            rect.bottom <= (window.innerHeight || document.documentElement.clientHeight) &&
            rect.right <= (window.innerWidth || document.documentElement.clientWidth)
        ) {
            // Если элемент видим и его верхняя граница меньше, чем текущая минимальная
            if (rect.top < minTop) {
                minTop = rect.top; // Обновляем минимальное значение top
                visibleCollectionTitle = title.getAttribute('aria-label'); // Обновляем название видимого элемента
            }
        }
    });

    // Возвращаем название самого верхнего видимого элемента
    return visibleCollectionTitle;
}

function() {
    var clickedElement = {{Click Element}};
    if (clickedElement && clickedElement.hasAttribute("title")) {
        return clickedElement.getAttribute("title");
    }
    return null;
}

function() {
  var userData = localStorage.getItem('profile'); // Замените 'userProfile' на реальный ключ
  if (userData) {
    try {
      var parsedData = JSON.parse(userData);
      return parsedData.profile && parsedData.profile.role ? parsedData.profile.role : 'undefined';
    } catch (error) {
      return 'undefined'; // Возвращаем значение по умолчанию при ошибке
    }
  }
  return 'undefined'; // Если данных нет
}

function() {
  var button = document.querySelector('.button_start_watch');
  if (button) {
    return button.textContent.trim();
  }
  return undefined;
}

function() {
  var SEL = '.items_slide.t_content-v';
  try { return document.querySelectorAll(SEL).length || 0; } catch(e){ return 0; }
}

function () {
  var el = {{Click Element}};
  if (!el) return;

  var container = el.closest('.items_slide');
  if (!container) return;

  return container.getAttribute('data-item_type');
}

function () {
  var el = {{Click Element}};
  if (!el) return;

  // --- 1. rowset → a.seo_link[title] ---
  var rowset = el.closest('.rowset');
  if (rowset) {
    var seoLink = rowset.querySelector('a.seo_link[title]');
    if (seoLink) {
      return seoLink.getAttribute('title');
    }
  }

  // --- 2. page_movies → h2.page_subhead ---
  var pageMovies = el.closest('.page_movies');
  if (pageMovies) {
    var h2 = pageMovies.querySelector('h2.page_subhead');
    if (h2) {
      return h2.textContent.trim();
    }
  }

  // --- 3. page_content → page_subhead → h1 ---
  var pageContent = el.closest('.page_content');
  if (pageContent) {
    var h1 = pageContent.querySelector('.page_subhead h1');
    if (h1) {
      return h1.textContent.trim();
    }
  }

  return;
}

function () {
  var el = {{Click Element}};
  if (!el) return;

  function getIdFromHref(href) {
    if (!href) return;
    return href.split('?')[0].split('/').pop();
  }

  // --- 1. rowset → a.seo_link[href] ---
  var rowset = el.closest('.rowset_wrap');
  if (rowset) {
    var seoLink = rowset.querySelector('a.seo_link[href]');
    if (seoLink) {
      return getIdFromHref(seoLink.getAttribute('href'));
    }
  }

  // --- 2. page_movies → берём из URL ---
  var pageMovies = el.closest('.page_movies');
  if (pageMovies) {
    var path = location.pathname;
    return getIdFromHref(path);
  }

  // --- 3. page_content → берём из URL ---
  var pageContent = el.closest('.page_content');
  if (pageContent) {
    var path = location.pathname;
    return getIdFromHref(path);
  }

  return;
}

function() {
  var el = {{Click Element}};
  if (!el) return undefined;

  // 1. Если кликнули прямо по img
  if (el.tagName === 'IMG') {
    return el.getAttribute('alt') || undefined;
  }

  // 2. Если img внутри элемента клика
  var img = el.querySelector && el.querySelector('img[alt]');
  if (img) {
    return img.getAttribute('alt') || undefined;
  }

  // 3. Ищем ближайший баннер / слайд выше по DOM
  var container = el.closest && el.closest('.promo-bg_block, .items_slide, .rowset_item');

  if (container) {
    // сначала лучше искать title-картинку внутри promo-bg_title
    var titleImg = container.querySelector('.promo-bg_title img[alt]');
    if (titleImg) {
      return titleImg.getAttribute('alt') || undefined;
    }

    // если title нет — берем любую картинку с alt внутри баннера
    var bannerImg = container.querySelector('img[alt]');
    if (bannerImg) {
      return bannerImg.getAttribute('alt') || undefined;
    }
  }

  return undefined;
}

function() {
  var el = {{Click Element}};
  if (!el) return undefined;

  // поднимаемся до ближайшей ссылки <a>
  var link = el.closest && el.closest('a');
  if (!link) return undefined;

  // 1. пробуем data-id
  var dataId = link.getAttribute('data-id');
  if (dataId) {
    return dataId;
  }

  // 2. fallback — href
  var href = link.getAttribute('href');
  if (href) {
    return href;
  }

  return undefined;
}

function () {
  var el = {{Click Element}};
  if (!el || !el.closest) return;

  var container = el.closest('.page_filter_cont');
  if (!container) return;

  var nameEl = container.querySelector('.page_filter_name');
  if (!nameEl) return;

  return (nameEl.textContent || '').trim();
}

function() {
  var el = {{Click Element}};

  if (!el) {
    return -1;
  }

  // 1. Первый вариант: промо / коллекции
  var itemSlide = el.closest('.items_slide');

  if (itemSlide && itemSlide.getAttribute('data-item_index') !== null) {
    return Number(itemSlide.getAttribute('data-item_index'));
  }

  // 2. Второй вариант: контентные карточки
  var rowsetItem = el.closest('.rowset_item_cont');

  if (rowsetItem && rowsetItem.getAttribute('data-index') !== null) {
    return Number(rowsetItem.getAttribute('data-index'));
  }

  return -1;
}

